// ============================================================================
// RED-BLACK TREE IMPLEMENTATION IN C++
// ============================================================================
//
// A Red-Black Tree is a self-balancing binary search tree where each node
// has a color (red or black) and satisfies the following properties:
//
// 1. Every node is either red or black.
// 2. The root is black.
// 3. All leaves (NIL/null pointers) are black.
// 4. If a node is red, then both its children are black.
// 5. For each node, all paths from the node to descendant leaves contain
//    the same number of black nodes.
//
// These properties ensure that the tree remains approximately balanced,
// guaranteeing O(log n) time complexity for insert, erase, and find
// operations in the worst case.
//
// This implementation includes:
// - Insertion with rebalancing
// - Erasure with rebalancing
// - Search/Find operations
// - Iterators for in-order, pre-order, post-order, and level-order traversal
// - Size tracking
// - Height calculation
// - Validation of red-black tree properties
// - Copy and move semantics
// - Comparison operators
// - String representation
// - Thread-safe wrapper (optional)
// - Comprehensive test suite
//
// ============================================================================

namespace rbtree {

// Forward declaration
template <typename Key, typename Value>
class RedBlackTree;

// ============================================================================
// NODE STRUCTURE
// ============================================================================

// Color enum for red-black tree nodes
enum class Color {
    RED,
    BLACK
};

// Node structure for the red-black tree
template <typename Key, typename Value>
struct Node {
    Key key;
    Value value;
    Color color;
    Node* left;
    Node* right;
    Node* parent;

    // Constructor
    Node(const Key& k, const Value& v, Color c = Color::BLACK)
        : key(k), value(v), color(c), left(nullptr), right(nullptr), parent(nullptr) {}

    // Move constructor
    Node(Node&& other) noexcept
        : key(std::move(other.key)),
          value(std::move(other.value)),
          color(other.color),
          left(other.left),
          right(other.right),
          parent(other.parent) {
        other.left = nullptr;
        other.right = nullptr;
        other.parent = nullptr;
        other.color = Color::BLACK;
    }

    // Copy constructor
    Node(const Node& other)
